const updateXSpacePeer = `-- name: UpdateXSpacePeer :execrows
UPDATE xspace_peers SET in_discover = ?1, in_questions = ?2, in_delegation = ?3,
  in_knowledge = ?4, in_kbs_json = ?5, disclosure = ?6,
  max_per_hour = ?7, max_pending = ?8, out_questions = ?9,
  out_delegation = ?10, out_knowledge = ?11, version = version + 1,
  updated_at = ?12, updated_by = ?13
WHERE space_id = ?14 AND peer_space_id = ?15 AND version = ?16
`

type UpdateXSpacePeerParams struct {
	InDiscover    int64
	InQuestions   int64
	InDelegation  int64
	InKnowledge   int64
	InKbsJson     string
	Disclosure    string
	MaxPerHour    int64
	MaxPending    int64
	OutQuestions  int64
	OutDelegation int64
	OutKnowledge  int64
	Now           int64
	By            string
	SpaceID       string
	PeerSpaceID   string
	Version       int64
}

func (q *Queries) UpdateXSpacePeer(ctx context.Context, arg UpdateXSpacePeerParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateXSpacePeer,
		arg.InDiscover,
		arg.InQuestions,
		arg.InDelegation,
		arg.InKnowledge,
		arg.InKbsJson,
		arg.Disclosure,
		arg.MaxPerHour,
		arg.MaxPending,
		arg.OutQuestions,
		arg.OutDelegation,
		arg.OutKnowledge,
		arg.Now,
		arg.By,
		arg.SpaceID,
		arg.PeerSpaceID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

